import { pathToFileURL } from 'node:url';
import { assert } from 'node:assert';

// debounce.ts
export function debounce(fn: (...args: any[]) => void, waitMs: number) {
    let timer: ReturnType<typeof setTimeout> | null = null;
    return (...args: any[]) => {
        if (timer !== null) {
            clearTimeout(timer);
        }
        timer = setTimeout(() => {
            fn(...args);
        }, waitMs);
    };
}

// Self-test when executed directly
if (import.meta.url === pathToFileURL(process.argv[1]).href) {
    // Test 1: Basic debounce delay
    let called = false;
    const debounced = debounce(() => {
        called = true;
    }, 100);

    // First call
    debounced();
    // Second call before delay
    debounced();

    // Wait for debounce to fire
    setTimeout(() => {
        assert(called, 'Basic debounce should have called');
        called = false;

        // Test 2: Multiple calls, only last should fire after delay
        let lastCallCount = 0;
        const debounced2 = debounce(() => {
            lastCallCount++;
        }, 50);

        debounced2();
        debounced2();
        debounced2();

        // Wait for debounce to fire once
        setTimeout(() => {
            assert(lastCallCount === 1, 'Only last call should fire after delay');
            // Test 3: Verify arguments are passed through
            let argsReceived: any[];
            const debounced3 = debounce((a, b) => {
                argsReceived = [a, b];
            }, 10);

            debounced3(1, 2);
            debounced3(3, 4);

            setTimeout(() => {
                assert(argsReceived === [3, 4], 'Latest arguments should be passed through');
                console.log('all tests passed');
            }, 20);
        }, 60);
    }, 120);
}

